/**
 * Anzeigenamen der Board-Spalten. Ohne dieses Mapping stünde der interne
 * Schlüssel in der E-Mail, also "inProgress" statt "In progress".
 */
const COLUMN_LABELS = {
  triage:     'Triage',
  toDo:       'To do',
  inProgress: 'In progress',
  await:      'Await feedback',
  done:       'Done',
};

/**
 * Zerlegt die Benachrichtigungs-Queue aus der RTDB in einzelne n8n-Items.
 *
 * Das Board legt beim Verschieben eines Tasks einen Eintrag unter
 * /notifications ab. Firebase liefert dort ein Objekt, dessen Schlüssel die
 * Push-IDs sind; der Schlüssel wird als "key" durchgereicht, weil der
 * nachgelagerte DELETE-Node den Eintrag darüber wieder entfernt.
 *
 * Ist die Queue leer, antwortet Firebase mit null und n8n verpackt das als
 * { data: null }. Beide Formen müssen zu einem leeren Ergebnis führen, sonst
 * liefe der Versand auf einem Pseudo-Eintrag.
 *
 * Einträge ohne Empfängeradresse werden verworfen: sie stammen aus Tasks,
 * deren Ersteller keine Adresse hinterlegt hat, und wären nicht zustellbar.
 *
 * @returns {Array<{json: {key: string, title: string, from: string, to: string, name: string, email: string}}>}
 */
const raw = $input.first().json ?? {};

// Leere Queue in beiden Ausprägungen abfangen
const queue = 'data' in raw && raw.data === null ? {} : raw;

return Object.entries(queue)
  .filter(([, entry]) => entry && typeof entry === 'object')
  .map(([key, entry]) => ({
    json: {
      key,
      title: entry.title,
      from:  COLUMN_LABELS[entry.from] ?? entry.from,
      to:    COLUMN_LABELS[entry.to]   ?? entry.to,
      name:  entry.recipient?.name  ?? '',
      email: entry.recipient?.email ?? '',
    },
  }))
  .filter(item => item.json.email);
